def matrixfy(name):
    if len(name) == 0:
        return "name must be at least one letter"

    import math
    size = math.ceil(math.sqrt(len(name)))
    matrix = []
    index = 0

    for i in range(size):
        row = []
        for j in range(size):
            if index < len(name):
                row.append(name[index])
            else:
                row.append('.')
            index += 1
        matrix.append(row)

    return matrix
